export type Kind = 'object' | 'character' | 'text';
export type Rect = { x: number; y: number; w: number; h: number };
export type Region = Rect & { id: string; kind: Kind; text: string; description: string; relation: string; colors: string[]; tags: string[]; locked?: boolean; raw_description?: string };
export type LayoutState = { caption: string; meta: string[]; canvas: string; palette: string[]; style: string; lighting: string; regions: Region[] };
export type Format = 'moss' | 'ming';
export type PromptKind = 'moss' | 'ming' | 'ideogram' | 'assistant';
export type Fit = 'cover' | 'contain' | 'fill' | 'actual';
export type GuideMode = 'off' | 'thirds' | 'golden' | 'both';
export type Size = { width: number; height: number };
export type Starter = { id: string; name: string; hint: string; canvas: string; meta: string[]; caption: string; items: Array<[Kind, number, number, number, number, string, string?]> };
export type Imported = { summary_caption?: string; meta?: string; canvas?: string; palette?: string; image_style?: string; ambient_lighting?: string; regions?: Array<Partial<Region>>; width?: number; height?: number; warnings?: string[] };
export type Guide = { axis: 'x' | 'y'; at: number };
export type GridItem = { label: string; caption: string; bbox: [number, number, number, number]; text?: string };

export const KINDS: Array<{ value: Kind; label: string }>;
export const CANVASES: Array<{ value: string; label: string }>;
export const META_SUGGESTIONS: string[];
export const PLACES: Array<{ value: string; label: string; rect: Rect }>;
export const STARTERS: Starter[];
export const PLACE_ONE: Array<[string, string, number, number, [number, number] | null]>;
export const PLACE_SPLIT: Array<[string, string, number, number]>;
export const GUIDES: Array<{ value: GuideMode; label: string }>;
export const FITS: Array<{ value: Fit; label: string }>;
export const FORMATS: Array<{ value: Format | 'ideogram'; label: string }>;
export function guideLines(mode: string): number[];
export function isGolden(value: number): boolean;
export const SNAP_PX: number;
export function clamp(value: number, low: number, high: number): number;
export function uid(): string;
export function splitList(text: string): string[];
export function pad2(value: number): string;
export function emptyState(): LayoutState;
export function newRegion(kind: Kind, rect: Rect): Region;
export function starterState(starter: Starter, caption?: string): LayoutState;
export function layoutPayload(state: LayoutState, size: Size, format?: 'compact' | 'pretty'): Record<string, string | number>;
export function mingPayload(state: LayoutState, size: Size, format?: 'compact' | 'pretty'): Record<string, string | number>;
export function payloadFor(format: Format, state: LayoutState, size: Size, output?: 'compact' | 'pretty'): Record<string, string | number>;
export function stateFromImport(imported: Imported): LayoutState;
export function stateFromMing(imported: Imported): LayoutState;
export function adaptState(state: LayoutState, format: Format): LayoutState;
export function foreignKind(value: unknown): 'ideogram' | 'assistant' | null;
export function formatOf(value: unknown): PromptKind | null;
export function promptFormat(text: string): PromptKind | null;
export function layoutInfo(text: string): { format: Format; items: number; text: number; caption: string } | null;
export function findLayout(value: unknown, depth?: number): string | null;
export function inferSourceSize(text: string, size: Size): Size | null;
export function normalizeLayout(text: string): { text: string; size: Size | null; locks: boolean[] };
export function regionsToGrid(regions: Region[]): GridItem[];
export function gridRect(bbox: number[]): Rect;
export function overlap(a: Rect, b: Rect): number;
export function keepLocked(previous: Region[], next: Region[]): Region[];
export function carryColours(previous: Region[], next: Region[]): Region[];
export function ocrLines(words: Array<{ label: string; bbox: number[] }>, size: Size, limit?: number): Array<{ text: string; bbox: number[] }>;
export function issueFromError(message: string, options?: { format?: Format; count?: number }): { number: number | null; need: 'caption' | 'text' | null; text: string };
export function fitRect(image: Size, fit: Fit, out: Size, size?: Size): Rect;
export function gridRects(columns: number, rows: number, cells: Array<[number, number]>, gapX?: number, gapY?: number): Rect[];
export function allCells(columns: number, rows: number): Array<[number, number]>;
export function placementRects(columns: number, rows: number, cells: Array<[number, number]> | null, size: Size, gutters?: boolean): Rect[];
export function alignRect<T extends Rect>(rect: T, where: 'left' | 'hcenter' | 'right' | 'top' | 'vcenter' | 'bottom'): T;
export function pixelRect(rect: Rect, patch: Partial<Record<'x' | 'y' | 'w' | 'h', number>>, size: Size): Rect;
export function toIdeogram(state: LayoutState): Record<string, unknown>;
export function keepAspect(sides: string, start: Rect, rect: { left: number; top: number; right: number; bottom: number }, ratio: number, centred: boolean, W: number, H: number): { left: number; top: number; right: number; bottom: number };
export function snapLines(regions: Region[], id: string, guides?: boolean | number[] | string): { x: number[]; y: number[] };
export function snapAxis(points: number[], lines: number[], pixels: number): { delta: number; line: number } | null;
export function dragRect(input: { mode: string; start: Rect; origin: { x: number; y: number }; point: { x: number; y: number }; size: Size; lines?: { x: number[]; y: number[] } | null; board?: Size | null; shift?: boolean; centred?: boolean }): { rect: Rect; guides: Guide[] };
export function clipboardFile(data: DataTransfer | null | undefined): File | null;
export function pngTexts(buffer: ArrayBuffer): Promise<string[]>;
export function fingerprint(text: string): string;
